param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}


$replacements=@(@(),@(63),@(65,66),@(55296,56320));$profiles=[Collections.Generic.List[object]]::new();$calls=0
function Capture-Write($Codec,[bool]$Encode,[int[]]$Source,[bool]$Stateful,[bool]$Flush){if($null -eq $Source){$Source=[int[]]@()};$destination=if($Encode){,[byte[]](@(99)*35)}else{,[char[]](@(99)*35)};try{$value=if($Encode){if($Stateful){$Codec.GetBytes([char[]][int[]]$Source,0,$Source.Count,$destination,1,$Flush)}else{$Codec.GetBytes([char[]][int[]]$Source,0,$Source.Count,$destination,1)}}else{if($Stateful){$Codec.GetChars([byte[]][int[]]$Source,0,$Source.Count,$destination,1,$Flush)}else{$Codec.GetChars([byte[]][int[]]$Source,0,$Source.Count,$destination,1)}};$result=[ordered]@{ok=$true;count=$value}}catch{$result=Failure-Of $_};return [ordered]@{result=$result;after=[int[]]$destination}}
foreach($kind in @('UTF8','UTF16LE','UTF16BE')){foreach($old in $replacements){foreach($next in $replacements){$rows=@()
 foreach($seedMode in 0..2){$prototype=switch($kind){'UTF8'{[Text.UTF8Encoding]::new($false,$false)};'UTF16LE'{[Text.UnicodeEncoding]::new($false,$true,$false)};'UTF16BE'{[Text.UnicodeEncoding]::new($true,$true,$false)}};$owner=[Text.Encoding]$prototype.Clone();$oldE=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$old));$oldD=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$old));$nextE=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$next));$nextD=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$next));$owner.EncoderFallback=$oldE;$owner.DecoderFallback=$oldD;$before=$owner.Clone();$encoder=$owner.GetEncoder();$decoder=$owner.GetDecoder();$seedChars=if($seedMode -eq 0){[int[]]@()}else{[int[]]@(55296)};$seedBytes=if($seedMode -eq 0){[int[]]@()}elseif($kind -eq 'UTF8'){if($seedMode -eq 1){[int[]]@(226)}else{[int[]]@(240,144)}}elseif($seedMode -eq 1){[int[]]@(0)}elseif($kind -eq 'UTF16LE'){[int[]]@(0,216)}else{[int[]]@(216,0)};$events=[ordered]@{};$events.seedEncoder=Capture-Write $encoder $true $seedChars $true $false;$events.seedDecoder=Capture-Write $decoder $false $seedBytes $true $false
 $owner.EncoderFallback=$nextE;$owner.DecoderFallback=$nextD;$after=$owner.Clone();$newEncoder=$owner.GetEncoder();$newDecoder=$owner.GetDecoder();$identity=[ordered]@{ownerEncoderNext=[object]::ReferenceEquals($owner.EncoderFallback,$nextE);ownerDecoderNext=[object]::ReferenceEquals($owner.DecoderFallback,$nextD);beforeEncoderOld=[object]::ReferenceEquals($before.EncoderFallback,$oldE);beforeDecoderOld=[object]::ReferenceEquals($before.DecoderFallback,$oldD);afterEncoderNext=[object]::ReferenceEquals($after.EncoderFallback,$nextE);afterDecoderNext=[object]::ReferenceEquals($after.DecoderFallback,$nextD);existingEncoderOld=[object]::ReferenceEquals($encoder.Fallback,$oldE);existingDecoderOld=[object]::ReferenceEquals($decoder.Fallback,$oldD);newEncoderNext=[object]::ReferenceEquals($newEncoder.Fallback,$nextE);newDecoderNext=[object]::ReferenceEquals($newDecoder.Fallback,$nextD)}
 $events.flushExistingEncoder=Capture-Write $encoder $true ([int[]]@()) $true $true;$events.flushExistingDecoder=Capture-Write $decoder $false ([int[]]@()) $true $true;$events.reuseExistingEncoder=Capture-Write $encoder $true ([int[]]@(56320)) $true $true;$events.reuseExistingDecoder=Capture-Write $decoder $false ([int[]]@(255)) $true $true
 foreach($entry in @(@('owner',$owner),@('before',$before),@('after',$after))){$events[($entry[0]+'Encoder')]=Capture-Write $entry[1] $true ([int[]]@(56320)) $false $true;$events[($entry[0]+'Decoder')]=Capture-Write $entry[1] $false ([int[]]@(255)) $false $true}
 $events.newEncoder=Capture-Write $newEncoder $true ([int[]]@(56320)) $true $true;$events.newDecoder=Capture-Write $newDecoder $false ([int[]]@(255)) $true $true;$calls+=$events.Count;$rows+=@([ordered]@{seedMode=$seedMode;seedChars=[int[]]@($seedChars | Where-Object {$null -ne $_});seedBytes=[int[]]@($seedBytes | Where-Object {$null -ne $_});identity=$identity;events=$events})
 };$profiles.Add([ordered]@{kind=$kind;oldReplacement=[int[]]$old;nextReplacement=[int[]]$next;rows=$rows})
}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeCalls=$calls;profiles=$profiles.ToArray();qualification='NATIVE_SELECTED_ENCODING_OWNER_FALLBACK_SNAPSHOTS_PENDING_FLUSH_AND_CLONES_ONLY; NO_ARBITRARY_CALLBACK_OR_TASK_ACCEPTANCE'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 15 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS owner/state fallback snapshots: $calls native calls"
